mapper.select:
SELECT h.task_id FROM task_head h WHERE 
AND h.status=#{status}
AND h.owner_id=#{ownerId}
AND h.updated_at >=#{updatedFrom}
AND h.updated_at <=#{updatedTo}
ORDER BY h.updated_at DESC,h.task_id DESC

SELECT document_type,owner_id,goal,based_on_document_revision,request_json,request_sha256,scope_json,scope_sha256,
  missing_requirements,requirements_sha256,schema_version,schema_manifest_sha256
FROM task_input_revision i WHERE project_id=#{projectId} AND task_id=#{taskId} AND task_revision=#{taskRevision}

SELECT m.tenant_id,m.project_id,m.snapshot_id,m.source_id,m.source_version,m.parse_version,m.index_version,m.approval_revision,m.binding_revision
FROM scope_member m WHERE m.project_id=#{projectId} AND m.snapshot_id=#{snapshotId}
ORDER BY m.source_version,m.parse_version
